import * as UTxORef from "./UTxORef.js"
import * as Tx from "./Tx.js"

const makePubKey = (byte: number): PubKey.PubKey =>
  Either.getOrThrow(PubKey.make(new Uint8Array(new Array(32).fill(byte))))

const makeRef = (byte: number, index = 0): UTxORef.UTxORef =>
  (`${byte.toString(16).padStart(2, "0")}`.repeat(32) +
    index.toString()) as UTxORef.UTxORef

const makeInput = (byte: number, pubKey: PubKey.PubKey): UTxO.UTxO =>
  UTxO.make(makeRef(byte), {
    address: Address.make(false, Credential.makePubKey(PubKey.hash(pubKey))),
    assets: { "": 1_000_000n }
  })

const makeWitness = (
  pubKey: PubKey.PubKey,
  byte: number
): Signature.Signature => ({
  pubKey,
  bytes: new Uint8Array(new Array(64).fill(byte))
})

