describe("validateSignatures", () => {
  it("accepts all required VK witnesses from inputs, withdrawals, dcerts, collateral and explicit signers", () => {
    const inputKey = makePubKey(0x11)
    const collateralKey = makePubKey(0x22)
    const withdrawalKey = makePubKey(0x33)
    const dcertKey = makePubKey(0x44)
    const requiredSigner = makePubKey(0x55)

    const tx: Tx.Tx = {
      ...Tx.empty,
      body: {
        ...Tx.empty.body,
        inputs: [makeInput(0x01, inputKey)],
        collateral: [makeInput(0x02, collateralKey)],
        withdrawals: [
          [
            RewardAddress.make(
              false,
              Credential.makePubKey(PubKey.hash(withdrawalKey))
            ),
            1n
          ]
        ],
        dcerts: [
          {
            _tag: "Delegation",
            credential: Credential.makePubKey(PubKey.hash(dcertKey)),
            poolId: PubKey.hash(makePubKey(0x66))
          } satisfies DCert.Delegation
        ],
        signers: [PubKey.hash(requiredSigner)]
      },
      witnesses: {
        ...Tx.empty.witnesses,
        signatures: [
          makeWitness(inputKey, 0x11),
          makeWitness(collateralKey, 0x22),
          makeWitness(withdrawalKey, 0x33),
          makeWitness(dcertKey, 0x44),
          makeWitness(requiredSigner, 0x55)
        ]
      }
    }

    expect(() => Effect.runSync(Tx.validateSignatures(tx))).not.toThrow()
  })

  it("fails when an input from a pubkey address is missing a witness", () => {
    const inputKey = makePubKey(0x77)

    const tx: Tx.Tx = {
      ...Tx.empty,
      body: {
        ...Tx.empty.body,
        inputs: [makeInput(0x03, inputKey)]
      },
      witnesses: Tx.empty.witnesses
    }

    expect(() => Effect.runSync(Tx.validateSignatures(tx))).toThrow(
      PubKey.hash(inputKey)
    )
  })

  it("fails when a withdrawal from a pubkey reward address is missing a witness", () => {
    const withdrawalKey = makePubKey(0x88)

    const tx: Tx.Tx = {
      ...Tx.empty,
      body: {
        ...Tx.empty.body,
        withdrawals: [
          [
            RewardAddress.make(
              false,
              Credential.makePubKey(PubKey.hash(withdrawalKey))
            ),
            1n
          ]
        ]
      },
      witnesses: Tx.empty.witnesses
    }

    expect(() => Effect.runSync(Tx.validateSignatures(tx))).toThrow(
      PubKey.hash(withdrawalKey)
    )
  })

  it("fails when a dcert pubkey action is missing a witness", () => {
    const operatorKey = makePubKey(0xaa)
    const ownerKey = makePubKey(0x99)

    const tx: Tx.Tx = {
      ...Tx.empty,
      body: {
        ...Tx.empty.body,
        dcerts: [
          {
            _tag: "RegisterPool",
            id: PubKey.hash(operatorKey),
            vrf: PubKey.hash(makePubKey(0xbb)),
            pledge: 0n,
            margin: 0,
            owners: [PubKey.hash(ownerKey)]
          } satisfies DCert.RegisterPool
        ]
      },
      witnesses: {
        ...Tx.empty.witnesses,
        signatures: [makeWitness(operatorKey, 0xaa)]
      }
    }

    expect(() => Effect.runSync(Tx.validateSignatures(tx))).toThrow(
      PubKey.hash(ownerKey)
    )
  })
})

describe("decode trusted conway tx with scripts and encoding/decoding roundtrip", () => {
  const signedTx =
    ""

  const decodeTx = (cborHex: string) =>
    Effect.runSync(
      Tx.decode({ trusted: true })(cborHex).pipe(
        Network.provideKnownUTxOs({
          "8c20a9ab7153e53d17a0b820b2d606b27257a1281d9365acc6d0d3cb8725ccc30": {
            ref: "8c20a9ab7153e53d17a0b820b2d606b27257a1281d9365acc6d0d3cb8725ccc30" as UTxORef.UTxORef,
            output: {
              address:
                "addr_test1vpvndky904g9whpnuae0ffsd37ysjjyu7m6avse3nqsfysqx3eg5h" as Address.Address,
              assets: { "": 9999835423n } satisfies Assets.Assets
            }
          } satisfies UTxO.UTxO
        })
      )
    )

  const tx = decodeTx(signedTx)

  const encodedFromFull = Tx.encode()(tx)

  const tx2 = decodeTx(Bytes.toHex(encodedFromFull))

  const encoded = Tx.encode()(tx2)

  expect(encodedFromFull).toEqual(encoded)
})

describe("full conway tx", () => {
  it("decode full conway tx preserves refscripts in witnesses smart and is valid", () => {
    const signedTx =
      ""

    const decodeTx = (cborHex: string) =>
      Effect.runSync(
        Tx.decode({ trusted: true })(cborHex).pipe(
          Network.provideKnownUTxOs({})
        )
      )

    const tx = decodeTx(signedTx)

    expect(Tx.isSmart(tx)).toBe(true)

    console.log(tx.witnesses.signatures.map((s) => PubKey.hash(s.pubKey)))

    Effect.runSync(
      Tx.validate({ strict: true })(tx).pipe(
        Effect.provideService(Network.Params.params, testParams)
      )
    )
  })
})
